<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue';import {api} from '../api';
type Item=Record<string,any>;const props=withDefaults(defineProps<{stage:string;taskId:string;showText?:boolean}>(),{showText:true});
const sources=ref<Item[]>([]),sourceIndex=ref(0),pageIndex=ref(0),scale=ref(1),error=ref(''),imageError=ref(false),busy=ref(false),uploading=ref(false),uploadError=ref(''),imageFile=ref<File|null>(null),documentFile=ref<File|null>(null),pdfPage=ref(1),printedPage=ref('');let epoch=0,alive=true;
const source=computed(()=>sources.value[sourceIndex.value]),page=computed(()=>source.value?.pages[pageIndex.value]);
watch(()=>[props.stage,props.taskId],async()=>{const current=++epoch;busy.value=true;error.value='';sources.value=[];sourceIndex.value=0;pageIndex.value=0;scale.value=1;try{const rows=await api(`/builder/reference-images/${props.stage}/${props.taskId}`);if(alive&&current===epoch)sources.value=rows}catch(e){if(alive&&current===epoch)error.value=(e as Error).message}finally{if(alive&&current===epoch)busy.value=false}},{immediate:true});
async function attach(){
 if(!source.value||!imageFile.value||!documentFile.value||uploading.value)return;
 const current=epoch,sourceId=source.value.id,file=imageFile.value,document=documentFile.value;uploading.value=true;uploadError.value='';
 try{
  if(file.size>10_000_000||!['image/png','image/jpeg'].includes(file.type)||document.size>100_000_000)throw new Error('请选择10 MB以内的PNG/JPEG原图和100 MB以内的原教材PDF。');
  const documentBytes=await document.arrayBuffer();if(new TextDecoder().decode(documentBytes.slice(0,5))!=='%PDF-')throw new Error('请选择原教材PDF。');
  const documentHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',documentBytes))).map(x=>x.toString(16).padStart(2,'0')).join('');
  const base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]!);reader.onerror=()=>reject(new Error('原图读取失败。'));reader.readAsDataURL(file)});
  await api(`/content/sources/${sourceId}/images`,{name:file.name,mimeType:file.type,base64,expectedSourceHash:source.value.hash,documentHash,page:pdfPage.value,printedPage:printedPage.value});
  const rows=await api(`/builder/reference-images/${props.stage}/${props.taskId}`);if(alive&&epoch===current){sources.value=rows;imageFile.value=null;documentFile.value=null;}
 }catch(e){if(alive&&epoch===current)uploadError.value=(e as Error).message}finally{if(alive)uploading.value=false}
}
watch(sourceIndex,()=>{pageIndex.value=0;scale.value=1});watch(page,()=>imageError.value=false);onUnmounted(()=>{alive=false;epoch++});
</script>
<template><section class="source-evidence" aria-label="原图与来源对照"><p v-if="busy" role="status">正在读取原图来源…</p><p v-if="error" class="warning" role="alert">{{error}}</p><p v-if="!busy&&!error&&!sources.length" class="muted">此记录没有保存教材来源关联，无法显示原图。</p><template v-if="source"><label v-if="sources.length>1">对照来源<select v-model="sourceIndex"><option v-for="(s,i) in sources" :value="i" :key="s.id">{{s.title}}</option></select></label><h3>{{source.title}}</h3><details v-if="stage==='sources'"><summary>补充此来源的教材原图</summary><p class="muted">原教材PDF只在本机计算指纹；保存所选页图片和页码供后续复核。请确认图片与本来源对应。</p><label>原教材PDF<input type="file" accept="application/pdf" :disabled="uploading" @change="documentFile=($event.target as HTMLInputElement).files?.[0]||null"></label><label>此页原图<input type="file" accept="image/png,image/jpeg" :disabled="uploading" @change="imageFile=($event.target as HTMLInputElement).files?.[0]||null"></label><label>PDF页序（从1开始）<input v-model.number="pdfPage" type="number" min="1" max="10000" :disabled="uploading"></label><label>书内页码或页标题<input v-model="printedPage" maxlength="100" :disabled="uploading"></label><p v-if="uploadError" class="warning" role="alert">{{uploadError}}</p><button :disabled="uploading||!imageFile||!documentFile||!printedPage.trim()" @click="attach">{{uploading?'正在保存原图…':'保存原图关联'}}</button></details><p class="muted">原图供人工核对；查看不会确认识别结果或提交审核。</p><div class="evidence-grid" :class="{single:!showText}"><div v-if="showText" class="source-copy"><h4>已保存的来源文字</h4><p class="transcription">{{source.text||'尚未保存识别文字。'}}</p><h4>分段结果 · {{source.chunks.length}} 段</h4><details v-for="c in source.chunks" :key="c.id"><summary>{{c.locator}}</summary><p class="transcription">{{c.text}}</p></details></div><div class="image-pane"><p v-if="!source.pages.length" class="muted">此来源尚未关联原图。请在来源中补充教材页；不会按标题猜测图片。</p><template v-if="page"><div class="image-toolbar"><label>原教材页<select v-model="pageIndex"><option v-for="(p,i) in source.pages" :key="p.id" :value="i">PDF 第 {{p.page}} 页 · {{p.printedPage}}</option></select></label><div><button :disabled="pageIndex===0" @click="pageIndex--">上一张原图</button><button :disabled="pageIndex+1>=source.pages.length" @click="pageIndex++">下一张原图</button><button :disabled="scale<=1" @click="scale=Math.max(1,scale-0.25)">缩小</button><button :disabled="scale>=3" @click="scale=Math.min(3,scale+0.25)">放大</button><button @click="scale=1">适合宽度</button></div></div><p class="muted">{{page.printedPage}} · PDF 第 {{page.page}} 页 · {{pageIndex+1}} / {{source.pages.length}} 张 · {{Math.round(scale*100)}}%</p><p v-if="source.pages.length>1" class="muted">左侧保留此来源全文和分段，请按页内文字对照；尚无逐段框选定位。</p><p v-if="imageError" role="alert" class="warning">原图加载失败，请检查登录状态并重新打开。</p><div class="image-scroll"><img :key="page.id" :src="page.url" :alt="`${source.title}，${page.printedPage}，PDF第${page.page}页原图`" :style="{width:scale*100+'%'}" @error="imageError=true"></div><details><summary>原图溯源信息</summary><p>教材指纹 {{page.documentHash}}</p><p>图片指纹 {{page.imageHash}}</p><p>来源编号 {{source.id}}</p></details></template></div></div></template></section></template>
<style scoped>.source-evidence{min-width:0}h3{font-size:16px;overflow-wrap:anywhere}.evidence-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:20px}.evidence-grid.single{grid-template-columns:minmax(0,1fr)}.source-copy,.image-pane{min-width:0}.source-copy{max-height:70dvh;overflow:auto;padding-right:12px}.transcription{white-space:pre-wrap;line-height:1.85;overflow-wrap:anywhere}.image-toolbar{position:sticky;top:0;background:#fafcf8;padding:6px 0;z-index:1}.image-toolbar>div{display:flex;gap:6px;flex-wrap:wrap}.image-toolbar button{padding:8px;font-size:13px}.image-scroll{overflow:auto;max-height:64dvh;border:1px solid #d7e3d4;background:#e6ece5}.image-scroll img{display:block;max-width:none;height:auto}.image-pane details p{overflow-wrap:anywhere;font-size:12px}details{margin:12px 0}select{max-width:100%}@media(max-width:760px){.evidence-grid{grid-template-columns:minmax(0,1fr)}.source-copy{max-height:35dvh}.image-scroll{max-height:58dvh}}
</style>
